import { describe, expect, it } from 'vitest';
import { parsePreferences, PREFERENCES_KEY, readPreferences, savePreferences } from './storage.ts';
import type { PreferenceStorage } from './storage.ts';

describe('saved preferences and storage failures', () => {
  it('accepts supported sizes and bounded integer bests, ignoring invalid values', () => {
    expect(parsePreferences(JSON.stringify({ size: 16, best: { 4: 8, 6: 999999, 8: 1000000,
      10: -1, 12: 2.5, 14: '3', 16: null, 5: 10 } }))).toEqual({ size: 16, best: { 4: 8, 6: 999999 } });
    for (const text of [null, '{', 'null', '[]', '4', '{"size":5}', '{"size":"6"}']) {
      expect(parsePreferences(text)).toEqual({ size: 4, best: {} });
    }
  });
  it('catches unavailable reads and writes and only writes the owned key', () => {
    const broken: PreferenceStorage = { getItem() { throw new Error('blocked'); }, setItem() { throw new Error('full'); } };
    expect(readPreferences(broken)).toEqual({ size: 4, best: {} });
    expect(() => savePreferences(broken, { size: 4, best: {} })).not.toThrow();
    expect(readPreferences(null)).toEqual({ size: 4, best: {} });
    const values = new Map([['unrelated', 'keep me']]);
    const storage: PreferenceStorage = { getItem: key => values.get(key) ?? null, setItem: (key, value) => { values.set(key, value); } };
    savePreferences(storage, { size: 8, best: { 8: 32 } });
    expect(values.get('unrelated')).toBe('keep me');
    expect(values.size).toBe(2);
    expect(values.has(PREFERENCES_KEY)).toBe(true);
    expect(readPreferences(storage)).toEqual({ size: 8, best: { 8: 32 } });
  });
});
import { describe, expect, it } from 'vitest';
import { faceIdentity } from './face.ts';

describe('face identities', () => {
  it('has 128 distinct shape, marker and fill names with exact public examples', () => {
    const faces = Array.from({ length: 128 }, (_, index) => faceIdentity(index));
    expect(new Set(faces.map(face => face.name)).size).toBe(128);
    expect(faces[0]?.name).toBe('cyan solid circle, marker top');
    expect(faces[64]?.name).toBe('cyan outline circle, marker top');
    expect(faces[127]?.name).toBe('ice outline chevron, marker top-left');
    for (const face of faces) expect(Math.hypot(face.markerX - 50, face.markerY - 50)).toBeCloseTo(40);
    const diagonal = faceIdentity(8);
    expect(diagonal.markerX).toBeCloseTo(78.284271);
    expect(diagonal.markerY).toBeCloseTo(21.715729);
  });
  it('rejects out of range identities', () => {
    for (const id of [-1, 128, NaN, 0.5]) expect(() => faceIdentity(id)).toThrow();
  });
});
import { describe, expect, it } from 'vitest';
import { focusDestination } from './navigation.ts';

describe('board focus movement', () => {
  it('moves within rows and columns without wrapping edges', () => {
    expect(focusDestination(5, 4, 'ArrowLeft')).toBe(4);
    expect(focusDestination(5, 4, 'ArrowRight')).toBe(6);
    expect(focusDestination(5, 4, 'ArrowUp')).toBe(1);
    expect(focusDestination(5, 4, 'ArrowDown')).toBe(9);
    expect(focusDestination(0, 4, 'ArrowLeft')).toBe(0);
    expect(focusDestination(3, 4, 'ArrowRight')).toBe(3);
    expect(focusDestination(0, 4, 'ArrowUp')).toBe(0);
    expect(focusDestination(255, 16, 'ArrowDown')).toBe(255);
    for (const key of ['Tab', 'Home', 'End', 'PageDown', 'a']) expect(focusDestination(0, 4, key)).toBeNull();
  });
});

