import { activateCard, advanceGame, createGame } from './state.ts';
import type { GameState } from './state.ts';
import { hasExactKeys, isNonnegativeInteger, isRecord, parseLimitedJson } from './validation.ts';

export const REPLAY_VERSION = 1;
export const MAX_REPLAY_BYTES = 1048576;
export const MAX_REPLAY_ACTIONS = 10000;
type ReplayAction = Readonly<{ atMs: number; index: number }>;

function decodeActions(value: unknown, state: GameState, endMs: number): readonly ReplayAction[] | null {
  if (!Array.isArray(value) || value.length > MAX_REPLAY_ACTIONS) return null;
  const actions: ReplayAction[] = [];
  let previous = 0;
  for (const action of value) {
    if (!isRecord(action) || !hasExactKeys(action, ['atMs', 'index'])
      || !isNonnegativeInteger(action.atMs) || action.atMs < previous || action.atMs > endMs
      || !isNonnegativeInteger(action.index, state.deck.length - 1)) return null;
    actions.push({ atMs: action.atMs, index: action.index });
    previous = action.atMs;
  }
  return actions;
}

export function replayGame(text: string): GameState | null {
  const value = parseLimitedJson(text, MAX_REPLAY_BYTES);
  if (!isRecord(value) || !hasExactKeys(value, ['version', 'boardCode', 'actions', 'endMs'])
    || value.version !== REPLAY_VERSION || typeof value.boardCode !== 'string'
    || !isNonnegativeInteger(value.endMs)) return null;
  let state = createGame(value.boardCode);
  if (!state) return null;
  const actions = decodeActions(value.actions, state, value.endMs);
  if (!actions) return null;
  let previous = 0;
  for (const action of actions) {
    state = activateCard(advanceGame(state, action.atMs - previous), action.index);
    previous = action.atMs;
  }
  return advanceGame(state, value.endMs - previous);
}

/work/src/game/deck.ts.content:
export const GRID_SIZES = [4, 6, 8, 10, 12, 14, 16] as const;
export type GridSize = (typeof GRID_SIZES)[number];
export const MAX_SEED = 2147483646;
const MODULUS = 2147483647;

export type Board = Readonly<{ code: string; size: GridSize; seed: number }>;

export function isGridSize(value: unknown): value is GridSize {
  return GRID_SIZES.some(size => size === value);
}

export function parseBoardCode(code: string): Board | null {
  const match = /^np1-(4|6|8|10|12|14|16)-([1-9][0-9]{0,9})$/.exec(code);
  if (!match || match[0] !== code) return null;
  const size = Number(match[1]);
  const seed = Number(match[2]);
  if (!isGridSize(size) || !Number.isInteger(seed) || seed > MAX_SEED) return null;
  return Object.freeze({ code, size, seed });
}

export function nextRandom(state: number): number {
  return (state * 16807) % MODULUS;
}

export function drawIndex(state: number, bound: number): Readonly<{ state: number; index: number }> {
  const limit = Math.floor(MAX_SEED / bound) * bound;
  let next = nextRandom(state);
  while (next - 1 >= limit) next = nextRandom(next);
  return { state: next, index: (next - 1) % bound };
}

export function generateDeck(board: Board): readonly number[] {
  const deck = Array.from({ length: board.size * board.size }, (_, index) => Math.floor(index / 2));
  let state = board.seed;
  for (let index = deck.length - 1; index > 0; index -= 1) {
    const draw = drawIndex(state, index + 1);
    state = draw.state;
    const current = deck[index];
    const other = deck[draw.index];
    if (current === undefined || other === undefined) throw new Error('Invalid shuffle position.');
    deck[index] = other;
    deck[draw.index] = current;
  }
  return Object.freeze(deck);
}

