    <h1>Neon Pairs — all 128 identities at 44px</h1><p>Rows 0–63: solid. Rows 64–127: outline. Marker directions advance every eight faces.</p>
    <main>${figures.join('')}</main></html>`;
  await mkdir('evidence', { recursive: true });
